BEGIN;
CREATE EXTENSION IF NOT EXISTS pgtap WITH SCHEMA extensions;
SET LOCAL search_path = public, extensions;
SELECT no_plan();
INSERT INTO auth.users(id,email) VALUES ('00000000-0000-4000-a073-000000000001','voice-opening@example.test');
INSERT INTO public.businesses(id,owner_id,name,business_type,slug) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26','00000000-0000-4000-a073-000000000001','Voice','general','voice-073');
INSERT INTO public.voice_pilot_settings(business_id,enabled) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26',true);
INSERT INTO public.subscriptions(business_id,stripe_customer_id,stripe_subscription_id,plan,status) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26','cus_voice','sub_voice','sms_and_chat','active');
INSERT INTO public.contacts(id,business_id,phone_number,source_channel) VALUES ('20000000-0000-4000-a073-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','+15555550101','voice');
INSERT INTO public.conversations(id,business_id,contact_id,channel) VALUES ('30000000-0000-4000-a073-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','20000000-0000-4000-a073-000000000001','voice');
INSERT INTO public.voice_sessions(id,business_id,conversation_id,call_control_id,call_session_id,caller_phone,called_phone,response_mode,status,reserved_seconds) VALUES ('40000000-0000-4000-a073-000000000001','ea848911-ef72-44a6-8cf3-c47b3959be26','30000000-0000-4000-a073-000000000001','control','session','+15555550101','+15742638634','voice','ringing',600);

INSERT INTO public.voice_pilot_testers(business_id,phone_number) VALUES ('ea848911-ef72-44a6-8cf3-c47b3959be26','+15555550101');
SELECT is((public.prepare_preinformed_voice_session('40000000-0000-4000-a073-000000000001')).id,NULL::uuid,'tester membership alone cannot bypass disclosure');
SELECT is((SELECT status FROM public.voice_sessions LIMIT 1),'ringing','unacknowledged call keeps normal startup');
UPDATE public.voice_pilot_testers SET prior_disclosure_acknowledged_at=now()+interval '1 minute';
SELECT is((public.prepare_preinformed_voice_session('40000000-0000-4000-a073-000000000001')).id,NULL::uuid,'acknowledgment must predate this call');
UPDATE public.voice_pilot_testers SET prior_disclosure_acknowledged_at=now()-interval '1 day',phone_number='+15555550102';
SELECT is((public.prepare_preinformed_voice_session('40000000-0000-4000-a073-000000000001')).id,NULL::uuid,'another caller acknowledgment does not apply');
UPDATE public.voice_pilot_testers SET phone_number='+15555550101';
UPDATE public.voice_pilot_settings SET enabled=false;
SELECT is((public.prepare_preinformed_voice_session('40000000-0000-4000-a073-000000000001')).id,NULL::uuid,'stop switch still blocks direct startup');
UPDATE public.voice_pilot_settings SET enabled=true;
UPDATE public.businesses SET ai_replies_paused_at=now();
SELECT is((public.prepare_preinformed_voice_session('40000000-0000-4000-a073-000000000001')).id,NULL::uuid,'paused business cannot use prior acknowledgment');
UPDATE public.businesses SET ai_replies_paused_at=NULL;
UPDATE public.subscriptions SET status='canceled';
SELECT is((public.prepare_preinformed_voice_session('40000000-0000-4000-a073-000000000001')).id,NULL::uuid,'inactive subscription blocks direct startup');
UPDATE public.subscriptions SET status='active';
SELECT is((public.prepare_preinformed_voice_session('40000000-0000-4000-a073-000000000001')).status,'starting','informed tester starts directly');
SELECT is((SELECT notice_completed_at FROM public.voice_sessions LIMIT 1),NULL::timestamptz,'does not claim a notice was played');
SELECT is((SELECT prior_disclosure_acknowledged_at FROM public.voice_sessions LIMIT 1),now()-interval '1 day','call stores actual prior acknowledgment');
SELECT is((SELECT media_start_requested_at FROM public.voice_sessions LIMIT 1),now(),'media timing stays separate from old acknowledgment');
SELECT is((public.prepare_preinformed_voice_session('40000000-0000-4000-a073-000000000001')).media_start_requested_at,now(),'retry preserves startup timing');
INSERT INTO public.voice_stream_credentials(session_id,token_hash,expires_at) VALUES ('40000000-0000-4000-a073-000000000001',repeat('b',64),now()+interval '1 minute');
SELECT is((public.consume_voice_stream(repeat('b',64))).id,'40000000-0000-4000-a073-000000000001'::uuid,'bound stream accepts verified prior acknowledgment');
SELECT is((public.consume_voice_stream(repeat('b',64))).id,NULL::uuid,'direct greeting cannot reuse credential');
SELECT ok(public.activate_voice_session('40000000-0000-4000-a073-000000000001','live-opening'),'worker can activate without inventing a notice');
SELECT is((public.prepare_preinformed_voice_session('40000000-0000-4000-a073-000000000001')).id,NULL::uuid,'replayed ring event cannot restart active call');
UPDATE public.voice_sessions SET created_at=now()-interval '2 minutes',media_start_requested_at=now()-interval '1 minute',phone_ended_at=now();
SELECT public.estimate_voice_telnyx_usage(100);
SELECT is((SELECT round(estimated_cost_usd,6) FROM public.voice_provider_usage WHERE provider='telnyx'),0.015900::numeric,'estimate counts streaming and recording without unused Polly speech cost');
SELECT ok(NOT has_function_privilege('anon','public.prepare_preinformed_voice_session(uuid)','EXECUTE'),'anonymous cannot prepare informed calls');
SELECT ok(NOT has_function_privilege('authenticated','public.prepare_preinformed_voice_session(uuid)','EXECUTE'),'account clients cannot bypass disclosure');
SELECT ok(has_function_privilege('service_role','public.prepare_preinformed_voice_session(uuid)','EXECUTE'),'only trusted service can prepare calls');
SELECT ok(NOT has_column_privilege('authenticated','public.voice_pilot_testers','prior_disclosure_acknowledged_at','UPDATE'),'account clients cannot write acknowledgment');
SELECT public.configure_voice_pilot(1,true,12000,'[{"phone":"+15555550101","label":"Renamed"}]'::jsonb,'00000000-0000-4000-a073-000000000001');
SELECT is((SELECT prior_disclosure_acknowledged_at FROM public.voice_pilot_testers LIMIT 1),now()-interval '1 day','settings edits preserve existing acknowledgment');
SELECT public.configure_voice_pilot(2,false,12000,'[]'::jsonb,'00000000-0000-4000-a073-000000000001');
SELECT public.configure_voice_pilot(3,true,12000,'[{"phone":"+15555550101"}]'::jsonb,'00000000-0000-4000-a073-000000000001');
SELECT is((SELECT prior_disclosure_acknowledged_at FROM public.voice_pilot_testers LIMIT 1),NULL::timestamptz,'removing and readding a tester restores spoken notice');
SELECT * FROM finish();
ROLLBACK;
